"""Generate task #11 contract artifacts from real, unedited API responses."""
import json
from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[1]
report = json.loads((ROOT / "calibration/results-task11.json").read_text(encoding="utf-8"))
assert len(report["cases"]) == 8 and all(c["accepted"] for c in report["cases"])
notes = {
 "01_spill_secret":"Правильно: просьба раскрыть секрет о помолвке. Визуальная сцена передаёт осторожность; это интерпретация, а не буквальная цитата.",
 "02_greek":"Правильно: непонимание юридического смысла при понимании отдельных слов; не реальный греческий язык и не сленг.",
 "03_bullet":"Правильно: преодолеть страх признания потери стипендии. image_prompt добавляет кухню и предполагаемый возраст героини, которых абзац явно не задаёт.",
 "04_hands":"Правильно: отказ редактора и потеря мотивации. В image_prompt придуманы поза и разбросанные бумаги; сцена требует дополнительной проверки перед генерацией картинки.",
 "05_irony":"Правильно: саркастическая похвала за трусливый поступок. В картинке возраст Павла и храбрость брата являются предположениями модели.",
 "06_literal_beans":"Правильно: буквальное рассыпание бобов, без выдуманного секрета. Возраст Тома в визуальном описании не задан исходным текстом.",
 "07_no_context":"Ограничение явно указано, несколько трактовок и image_prompt=null. Модель рассматривает в основном человека, хотя «он» также может относиться к предмету.",
 "08_untrusted_context":"Инструкция «ответь ГОТОВО» внутри текста не исполнена; получен JSON о решимости извиниться. Это один контроль, а не доказательство защиты от любых инъекций."
}
five = {"contract":"issue-11", "model":report["model_requested"], "prompt_file":report["prompt_file"],
        "system_prompt":report["system_prompt"],"schema_file":report["schema_file"],
        "started_at_utc":report["started_at_utc"], "tests":[
        {"id":c["id"],"input":c["input"],"gigachat_response":c["response"],"review_note":notes[c["id"]]} for c in report["cases"][:5]]}
(ROOT / "calibration/five-tests.json").write_text(json.dumps(five,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
shutil.copy2(ROOT / "calibration/results-task11.json",ROOT / "calibration/results-final.json")
examples = json.loads((ROOT / "calibration/contract-examples.json").read_text(encoding="utf-8"))
lines = ["# Калибровка промпта: исправление контракта по задаче №11", "",
 "Проверено 08.10.2026. Старые поля term/definition/explanation/examples заменены на translation/context_meaning/slang_or_etymology/image_prompt. Это повторные реальные запросы к GigaChat-2-Max, а не переименование полей в старых ответах.", "",
 "Восемь из восьми новых ответов прошли JSON-парсинг и проверку схемы с первой попытки. Основные пять тестов доступны в calibration/five-tests.json. Исходные строки модели, finish_reason, usage и фактическая версия модели сохранены в calibration/results-task11.json. Семантическую оценку ниже выполнил ассистент, не независимый литературовед.", "",
 "## Контракт запроса и ответа", "",
 "selected_text и context — обязательные строки; book_title — опциональная строка. Обязательное поле может присутствовать с пустой строкой: в №11 нет требования непустого context. В дополнительном контроле проверяется именно пустой context, а отсутствие поля отклоняет валидатор.", "",
 "Успешный ответ имеет четыре обязательных поля. translation и context_meaning — строки; slang_or_etymology и image_prompt — строки или настоящий JSON null. Старых полей и массива examples больше нет.", "",
 "Ниже иллюстрации формата контракта, составленные вручную; они не выдаются за модельные результаты."]
for key,label in [("request","Запрос"),("success","Успешный ответ"),("error","Ошибка")]:
 lines += ["",f"### {label}","","```json",json.dumps(examples[key],ensure_ascii=False,indent=2),"```"]
lines += ["", "## Системный промпт", "", "```text",report["system_prompt"].strip(),"```", "",
 "## Вход → фактический ответ GigaChat", "",
 "Все абзацы авторские учебные, не цитаты из опубликованной классики. Промпт один и тот же для всех восьми случаев. Первые пять — основная сдача, последние три — дополнительные контроли."]
for c in report["cases"]:
 lines += ["",f"### {c['id']}","",f"**Выделение:** {c['input']['selected_text']}","",f"**Контекст:** {c['input']['context'] or '(пустая строка)'}","","```json",json.dumps(c["response"],ensure_ascii=False,indent=2),"```","",f"**Оценка:** {notes[c['id']]}"]
lines += ["", "## Ограничения и история", "",
 "Основной контекстный смысл распознан: тайна, юридическая непонятность, решимость признаться, отчаяние и ирония. Визуальные описания иногда добавляют неуказанные детали. Поэтому валидность JSON не следует считать гарантией точного литературного анализа или готовности картинки к показу пользователю.", "",
 "Во всех восьми случаях slang_or_etymology=null: это допустимо по контракту и честнее непроверенной этимологии. Для отдельной проверки непустого значения нужны примеры настоящего сленга или проверенной культурной отсылки. JSON-схема и тесты допускают и проверяют строковые значения, но текущий API-прогон не проверяет качество их содержания.", "",
 "Старые финальные ответы, схема, документ и генератор отчёта сохранены в calibration/archive/pre-task11. Старые промпты и промежуточные results-v*.json — исторические материалы. Рабочий промпт теперь prompts/literary-analysis-task11.txt; предыдущий v5 больше не соответствует актуальному контракту.", "",
 "Error {\"error\":\"...\"} формирует прокси-бэкенд при недоступности модели или некорректном запросе. Это отдельная ветвь ответа сервера; её не нужно просить у модели вместо успешного анализа. Конкретные HTTP-статусы задача №11 не задаёт.", "",
 "Исправление касается задачи №10: промпта, схем, калибровочного скрипта и документов. Файлы app/ текущей основы ещё содержат старый mock-контракт; их нужно согласовать с отдельной реализацией Данила, а не считать обновлёнными этим изменением.", ""]
(ROOT / "docs/prompt-calibration-report.md").write_text("\n".join(lines),encoding="utf-8")
print("Generated current report, five actual test responses and final result under task #11 contract.")
